// Generated by ArduSim from screens.json: edit it on the Экраны tab. Changes made here are overwritten.
#include "ui_screens.h"

LiquidCrystal_I2C uiDisplay(0x27, 20, 4);

static UiScreen uiScreen = UI_HOME;
static uint32_t uiEnteredAt;
static uint32_t uiValuesAt;
static uint8_t uiMenuIndex;
static uint8_t uiMenuTop;

// Text and values go through these, so that the screens below say only what and where.
static void uiAt(int x, int y, int size) {
  (void)size;
  uiDisplay.setCursor(x, y);
}

static void uiClear() {
  uiDisplay.clear();
}

static void uiShow() {
}

// A value's own cells: padded, so that a shorter one leaves nothing behind.
static void uiPrintField(const char* text, uint8_t width) {
  uint8_t used = 0;
  while (text[used] != 0 && used < width) {
    uiDisplay.print(text[used++]);
  }
  while (used++ < width) {
    uiDisplay.print(' ');
  }
}

static const __FlashStringHelper* uiItem_menu1(uint8_t index) {
  switch (index) {
    case 0: return F("Sensor");
    case 1: return F("About");
    case 2: return F("Back");
    default: return F("");
  }
}

static void uiDrawMenu_menu1() {
  uiAt(0, 1, 1);
  if (uiMenuTop + 0 < 3) {
    uiDisplay.print(uiMenuTop + 0 == uiMenuIndex ? '>' : ' ');
    uiDisplay.print(uiItem_menu1(uiMenuTop + 0));
  }
  uiAt(0, 2, 1);
  if (uiMenuTop + 1 < 3) {
    uiDisplay.print(uiMenuTop + 1 == uiMenuIndex ? '>' : ' ');
    uiDisplay.print(uiItem_menu1(uiMenuTop + 1));
  }
  uiAt(0, 3, 1);
  if (uiMenuTop + 2 < 3) {
    uiDisplay.print(uiMenuTop + 2 == uiMenuIndex ? '>' : ' ');
    uiDisplay.print(uiItem_menu1(uiMenuTop + 2));
  }
}

// Главный
static void uiDraw_home() {
  uiAt(0, 0, 1);
  uiDisplay.print(F("ArduSim screens"));
  uiAt(0, 2, 1);
  uiDisplay.print(F("Up:"));
  {
    char text[6] = "";
    uiValue_uptime(text, sizeof text);
    uiAt(4, 2, 1);
    uiPrintField(text, 5);
  }
  uiAt(0, 3, 1);
  uiDisplay.print(F("Press knob: menu"));
}

// Датчик
static void uiDraw_screen1() {
  uiAt(0, 0, 1);
  uiDisplay.print(F("Sensor on A0"));
  {
    char text[6] = "";
    uiValue_adc(text, sizeof text);
    uiAt(0, 1, 1);
    uiPrintField(text, 5);
  }
  uiAt(0, 3, 1);
  uiDisplay.print(F("Press knob: menu"));
}

// О программе
static void uiDraw_screen2() {
  uiAt(0, 0, 1);
  uiDisplay.print(F("Made on the map"));
  uiAt(0, 1, 1);
  uiDisplay.print(F("of the Screens tab"));
}

// Меню
static void uiDraw_menu1() {
  uiAt(0, 0, 1);
  uiDisplay.print(F("Menu"));
  uiDrawMenu_menu1();
}

static void uiDrawScreen() {
  uiClear();
  switch (uiScreen) {
    case UI_HOME:
      uiDraw_home();
      break;
    case UI_SCREEN1:
      uiDraw_screen1();
      break;
    case UI_SCREEN2:
      uiDraw_screen2();
      break;
    case UI_MENU1:
      uiDraw_menu1();
      break;
    default:
      break;
  }
  uiShow();
}

// What changes on its own. A character display rewrites only these cells; an OLED, its whole buffer.
static void uiDrawValues() {
  switch (uiScreen) {
    case UI_HOME:
      {
        char text[6] = "";
        uiValue_uptime(text, sizeof text);
        uiAt(4, 2, 1);
        uiPrintField(text, 5);
      }
      break;
    case UI_SCREEN1:
      {
        char text[6] = "";
        uiValue_adc(text, sizeof text);
        uiAt(0, 1, 1);
        uiPrintField(text, 5);
      }
      break;
    default:
      break;
  }
}

static void uiEnter(UiScreen next) {
  uiScreen = next;
  uiEnteredAt = millis();
  uiMenuIndex = 0;
  uiMenuTop = 0;
  uiDrawScreen();
}

void uiGoTo(UiScreen screen) {
  uiEnter(screen);
}

void uiRedraw() {
  uiDrawScreen();
}

UiScreen uiCurrent() {
  return uiScreen;
}

void uiSend(UiEvent event) {
  switch (uiScreen) {
    case UI_HOME:
      switch (event) {
        case UI_ON_ENC1_PRESS:
          uiEnter(UI_MENU1);
          return;
        default:
          break;
      }
      break;
    case UI_SCREEN1:
      switch (event) {
        case UI_ON_ENC1_PRESS:
          uiEnter(UI_MENU1);
          return;
        default:
          break;
      }
      break;
    case UI_SCREEN2:
      break;
    case UI_MENU1:
      switch (event) {
        case UI_ON_ENC1_LEFT:
          if (uiMenuIndex > 0) {
            uiMenuIndex--;
            if (uiMenuIndex < uiMenuTop) {
              uiMenuTop = uiMenuIndex;
            }
            uiDrawScreen();
          }
          return;
        case UI_ON_ENC1_RIGHT:
          if (uiMenuIndex + 1 < 3) {
            uiMenuIndex++;
            if (uiMenuIndex >= uiMenuTop + 3) {
              uiMenuTop = uiMenuIndex - 2;
            }
            uiDrawScreen();
          }
          return;
        case UI_ON_ENC1_PRESS:
          switch (uiMenuIndex) {
            case 0: uiEnter(UI_SCREEN1); break;
            case 1: uiEnter(UI_SCREEN2); break;
            case 2: uiEnter(UI_HOME); break;
            default: break;
          }
          return;
        default:
          break;
      }
      break;
    default:
      break;
  }

  // From any screen.
  switch (event) {
    case UI_ON_BTN1:
      uiEnter(UI_HOME);
      break;
    default:
      break;
  }
}

struct UiButton {
  uint8_t pin;
  bool activeLow;
  UiEvent event;
  bool pressed;
  bool raw;
  uint32_t changedAt;
};

static UiButton uiButtons[] = {
  {2, true, UI_ON_ENC1_PRESS, false, false, 0},
  {7, true, UI_ON_BTN1, false, false, 0},
};
static const uint8_t uiButtonCount = 2;

static void uiReadButtons() {
  uint32_t now = millis();
  for (uint8_t i = 0; i < uiButtonCount; i++) {
    UiButton& button = uiButtons[i];
    bool level = digitalRead(button.pin) == HIGH;
    bool raw = button.activeLow ? !level : level;
    if (raw != button.raw) {
      button.raw = raw;
      button.changedAt = now;
    }
    if (raw != button.pressed && now - button.changedAt >= 20) {
      button.pressed = raw;
      if (raw) {
        uiSend(button.event);
      }
    }
  }
}

static void uiReadEncoder_enc1() {
  static int last = HIGH;
  int now = digitalRead(4);
  if (now == LOW && last == HIGH) {
    uiSend(digitalRead(3) == HIGH ? UI_ON_ENC1_RIGHT : UI_ON_ENC1_LEFT);
  }
  last = now;
}

void uiBegin() {
  uiDisplay.init();
  uiDisplay.backlight();
  for (uint8_t i = 0; i < uiButtonCount; i++) {
    pinMode(uiButtons[i].pin, uiButtons[i].activeLow ? INPUT_PULLUP : INPUT);
  }
  pinMode(4, INPUT_PULLUP);
  pinMode(3, INPUT_PULLUP);
  uiEnter(uiScreen);
}

void uiUpdate() {
  uiReadButtons();
  uiReadEncoder_enc1();

  uint32_t now = millis();
  switch (uiScreen) {
    case UI_SCREEN2:
      if (now - uiEnteredAt >= 800UL) {
        uiEnter(UI_HOME);
      }
      break;
    default:
      break;
  }

  if (now - uiValuesAt >= 250UL) {
    uiValuesAt = now;
    uiDrawValues();
  }
}
